        offset <= iov[0].iov_len && bytes <= iov[0].iov_len - offset) {
        memcpy(buf, iov[0].iov_base + offset, bytes);
        return bytes;
    } else {
        return iov_to_buf_full(iov, iov_cnt, offset, buf, bytes);
    }
}

static inline int is_broadcast_ether_addr(const uint8_t *addr) /* <=== is_broadcast_ether_addr */ 
{
    return (addr[0] & addr[1] & addr[2] & addr[3] & addr[4] & addr[5]) == 0xff;
}

static inline int is_multicast_ether_addr(const uint8_t *addr) /* <=== is_multicast_ether_addr */ 
{
    return 0x01 & addr[0];
}

static inline eth_pkt_types_e /* <=== get_eth_packet_type */ 
get_eth_packet_type(const struct eth_header *ehdr)
{
    if (is_broadcast_ether_addr(ehdr->h_dest)) {
        return ETH_PKT_BCAST;
    } else if (is_multicast_ether_addr(ehdr->h_dest)) {
        return ETH_PKT_MCAST;
    } else { /* unicast */
        return ETH_PKT_UCAST;
    }
}

static void vmxnet_tx_pkt_calculate_hdr_len(struct VmxnetTxPkt *pkt) /* <=== vmxnet_tx_pkt_calculate_hdr_len */ 
{
